<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import TaskStepper from '../components/TaskStepper.vue';import TaskTimeline from '../components/TaskTimeline.vue';import {ApiError,api,type ExecutionPlan,type Task,type TaskEvent} from '../services/api'
const route=useRoute(),router=useRouter(),task=ref<Task|null>(null),plan=ref<ExecutionPlan|null>(null),ack=ref(false),busy=ref(false),error=ref(''),events=ref<TaskEvent[]>([]);const active=computed(()=>plan.value?.operations.filter(o=>['move','copy'].includes(o.action))||[]);const root=computed(()=>active.value[0]?.target_path?.replace(/[\\/][^\\/]+[\\/][^\\/]+$/,'')||'无目标');let timer=0
async function poll(){if(!task.value)return;const batch=await api.events(task.value.id,events.value.at(-1)?.seq||0);events.value.push(...batch.items);task.value=await api.task(task.value.id)}
onMounted(async()=>{try{const id=String(route.params.id);task.value=await api.task(id);plan.value=await api.plan(id,String(route.query.plan||''));await poll();timer=window.setInterval(()=>poll().catch(e=>{error.value=String(e)}),1000)}catch(e){error.value=String(e)}})
onBeforeUnmount(()=>window.clearInterval(timer))
const executionErrors:Record<string,string>={PLAN_NOT_APPROVED:'计划尚未批准，请重新核对并批准。',PLAN_STALE:'分类、审阅或授权已变化，请重新生成计划。',PLAN_HASH_MISMATCH:'计划内容与已批准 hash 不一致，已阻止执行。',REVISION_CONFLICT:'任务已在其他页面发生变化，请返回审阅页重新生成计划。',SOURCE_CHANGED:'源文件已变化，已安全保留原文件。',SOURCE_MISSING:'源文件不存在，已安全停止。',TARGET_EXISTS:'目标位置已存在文件，不会覆盖。',TARGET_CONFLICT:'目标路径冲突，不会覆盖。',GRANT_INVALID:'目录授权已失效，请重新授权。',INSUFFICIENT_SPACE:'目标磁盘空间不足。',OPERATION_FAILED:'文件操作失败，请查看操作日志。'}
async function execute(){if(busy.value||!task.value||!plan.value||!ack.value)return;busy.value=true;error.value='';try{const current=await api.task(task.value.id);task.value=current;const original={id:plan.value.plan_id,hash:plan.value.plan_hash};await api.approvePlan(current.id,current.revision,plan.value);const verified=await api.plan(current.id,original.id);if(verified.plan_id!==original.id||verified.plan_hash!==original.hash||!verified.approved)throw new ApiError('PLAN_STALE','批准后的计划验证失败',null,409);plan.value=verified;const latest=await api.task(current.id);task.value=latest;await api.executePlan(current.id,latest.revision,verified);task.value=await api.task(current.id);if(['COMPLETED','COMPLETED_WITH_ISSUES'].includes(task.value.status))await router.push(`/tasks/${task.value.id}/report`)}catch(e){error.value=e instanceof ApiError?(executionErrors[e.code]||`${e.code}：${e.message}`):String(e)}finally{busy.value=false}}
async function pause(){if(!task.value)return;try{task.value=await api.task(task.value.id);task.value=await api.pauseTask(task.value.id,task.value.revision)}catch(e){error.value=String(e)}}
</script>
<template><section class="page"><TaskStepper :current="4"/><p class="eyebrow">FINAL AUTHORIZATION</p><h1>确认并执行整理计划</h1><p class="lead">目标、冲突规则和 plan hash 已冻结；执行时不会覆盖已存在文件。</p><p v-if="error" class="notice danger-notice">{{error}}</p><div v-if="plan" class="run-layout"><section class="state-card"><h2>操作清单</h2><div v-for="op in plan.operations" :key="op.operation_id" class="operation-row"><span>{{op.action}}</span><code>{{op.source_path}}</code><b>→</b><code>{{op.target_path||'原地保留'}}</code></div><h2>持久检查点</h2><TaskTimeline :events="events"/></section><aside class="state-card"><h2>最终确认</h2><p>目标根：<code>{{root}}</code></p><p>可执行 {{active.length}} 项 · keep_both 不覆盖</p><p>hash：<code>{{plan.plan_hash}}</code></p><label class="ack"><input v-model="ack" type="checkbox"/> 我已核对目标与计划 hash</label><button class="primary-button" :disabled="!ack||busy" @click="execute">{{busy?'正在安全执行…':`批准并${task?.settings.operation_mode==='copy'?'复制':'移动'} ${active.length} 项`}}</button><button v-if="busy" class="secondary-button" @click="pause">在安全检查点暂停</button><p v-if="task?.status==='PAUSE_REQUESTED'" class="notice">暂停已请求；当前文件核验完成后停止。</p><p v-if="task?.status==='PAUSED'" class="notice">任务已暂停，未完成项仍保留在同一计划中。</p></aside></div><div v-else class="state-card">正在读取计划…</div></section></template>
